// C++14 is required for decltype(auto)

decltype(auto) f1() {
  int x = 0;
  return x;       // Returns a copy of x. decltype(x) is int.
                  // f1's return type is int.
}

decltype(auto) f2() {
  int x = 0;
  return (x);     // DANGER: Returns a reference to x.
                  // decltype((x)) is int&.
                  // f2's return type is int&.
                  // This is undefined behavior.
}
